public class NodeUtil_isValidQualifiedName_TriageGen1Test {

    @Test
    public void testIsValidQualifiedName_ValidSingleName() {
        assertTrue(NodeUtil.isValidQualifiedName("foo"));
    }

    @Test
    public void testIsValidQualifiedName_ValidQualifiedName() {
        assertTrue(NodeUtil.isValidQualifiedName("foo.bar.baz"));
    }

    @Test
    public void testIsValidQualifiedName_StartsWithDot() {
        assertFalse(NodeUtil.isValidQualifiedName(".foo"));
    }

    @Test
    public void testIsValidQualifiedName_EndsWithDot() {
        assertFalse(NodeUtil.isValidQualifiedName("foo."));
    }

    @Test
    public void testIsValidQualifiedName_InvalidSimpleNamePart() {
        // Assuming isValidSimpleName returns false for empty strings or special chars
        // This tests the loop and the branch where isValidSimpleName is false
        assertFalse(NodeUtil.isValidQualifiedName("foo..bar"));
    }

    @Test
    public void testIsValidQualifiedName_InvalidPartContent() {
        // Testing a name where one part is invalid (e.g., starting with a digit if that's the rule)
        // Since we don't see isValidSimpleName, we test the logic flow
        assertFalse(NodeUtil.isValidQualifiedName("foo.123bar")); 
    }

    @Test
    public void testIsValidQualifiedName_EmptyString() {
        // Depending on implementation of isValidSimpleName, 
        // but covers the split/loop logic
        assertFalse(NodeUtil.isValidQualifiedName(""));
    }

    @Test
    public void testIsValidQualifiedName_OnlyDot() {
        // This hits the startsWith/endsWith check
        assertFalse(NodeUtil.isValidQualifiedName("."));
    }
}
